import type { ComboboxGroupProps } from "../combobox.types";

import { forwardRef } from "react";
import { clsx } from "clsx";

import { ComboboxClasses } from "../combobox.styles";

const ComboboxGroup = forwardRef<HTMLDivElement, ComboboxGroupProps>(
  ({ children, className, ...props }, ref) => {
    return (
      <div ref={ref} className={clsx(ComboboxClasses.group, className)} {...props}>
        {children}
      </div>
    );
  },
);

ComboboxGroup.displayName = "Combobox.Group";

export { ComboboxGroup };
